import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class DigitRunReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String scan(String text) {
        try {
            int[] found = DigitRunReader.readNumbers(
                    new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8)));
            return found == null ? "null" : java.util.Arrays.toString(found);
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("digits between letters", "[12, 345]", scan("ab12cd345x"));
        check("number at the very end", "[7]", scan("value 7"));
        check("negative number", "[-12]", scan("a-12b"));
        check("lone dash is skipped", "[12]", scan("a-b12"));
        check("dash then dash then digits", "[-5]", scan("--5"));
        check("subtraction reads as negative", "[10, -20]", scan("10-20"));
        check("no numbers at all", "[]", scan("hello there"));
        check("empty stream", "[]", scan(""));
        check("dash at end of stream", "[3]", scan("3-"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

