import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.util.ArrayList;
import java.util.List;

public class DigitRunReader {

    public static int[] readNumbers(InputStream in) throws IOException {
        PushbackInputStream pushback = new PushbackInputStream(in);
        List<Integer> numbers = new ArrayList<>();
        int c = pushback.read();
        while (c != -1) {
            if (c == '-') {
                int next = pushback.read();
                if (next >= '0' && next <= '9') {
                    numbers.add(-readRun(pushback, next));
                } else if (next != -1) {
                    pushback.unread(next);
                }
            } else if (c >= '0' && c <= '9') {
                numbers.add(readRun(pushback, c));
            }
            c = pushback.read();
        }
        int[] result = new int[numbers.size()];
        for (int i = 0; i < result.length; i++) {
            result[i] = numbers.get(i);
        }
        return result;
    }

    private static int readRun(PushbackInputStream pushback, int firstDigit) throws IOException {
        int value = firstDigit - '0';
        int c = pushback.read();
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = pushback.read();
        }
        if (c != -1) {
            pushback.unread(c);
        }
        return value;
    }
}
